// Review links carry the enquiry id and its random review token. Anything malformed becomes a
// harmless lookup that matches nothing (and never reaches a ::uuid cast that would throw).
const q = $json.query ?? {};
const ok = /^[0-9a-f-]{36}$/i.test(q.id ?? '') && /^[0-9a-f]{32}$/i.test(q.t ?? '');
return [{ json: { id: ok ? q.id : '00000000-0000-0000-0000-000000000000', t: ok ? q.t : 'invalid' } }];

// The review page. Everything from the database is escaped - enquiry and draft text are untrusted.
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const row = $input.first()?.json ?? {};
const { id, t } = $('read query').first().json;
const page = (title, inner) => `<!doctype html><html><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title>
<style>body{font:16px/1.45 system-ui,sans-serif;max-width:640px;margin:0 auto;padding:16px;color:#111;background:#fafafa}
h1{font-size:20px}.card{background:#fff;border:1px solid #ddd;border-radius:10px;padding:12px 14px;margin:12px 0}
.k{color:#666;font-size:13px}.why{background:#fff4e5;border-color:#f0b35a}pre{white-space:pre-wrap;font:inherit;margin:4px 0}
button{font-size:17px;padding:12px 16px;border-radius:10px;border:0;margin:6px 6px 0 0}
.ok{background:#1a7f37;color:#fff}.take{background:#444;color:#fff}.done{color:#1a7f37;font-weight:600}</style></head>
<body>${inner}</body></html>`;

if (!row.id) {
  return [{ json: { status: 404, html: page('Not found', '<h1>Link not valid</h1><p>This review link is unknown or has expired.</p>') } }];
}
const pending = row.review_status === 'pending';
const hasDraft = String(row.draft ?? '').trim() !== '';
const form = (what, label, cls) => `<form method="post" action="review-act-staging" style="display:inline">
<input type="hidden" name="id" value="${esc(id)}"><input type="hidden" name="t" value="${esc(t)}">
<input type="hidden" name="do" value="${what}"><button class="${cls}">${label}</button></form>`;

const inner = `<h1>Enquiry review</h1>
<div class="k">${esc(row.category)} · action <b>${esc(row.action)}</b> · received ${esc(row.received_at)}</div>
<div class="card"><div class="k">Customer wrote</div><pre>${esc(row.body)}</pre></div>
${hasDraft ? `<div class="card"><div class="k">Drafted reply (not sent)</div><pre>${esc(row.draft)}</pre></div>`
           : `<div class="card"><div class="k">No AI draft</div>Escalated before drafting — a person writes this one.</div>`}
${row.reason ? `<div class="card why"><div class="k">Why it needs a human</div>${esc(row.reason)}</div>` : ''}
${pending
  ? (hasDraft ? form('approve', 'Approve draft', 'ok') : '') + form('takeover', 'Take over', 'take')
  : `<p class="done">Already reviewed: ${esc(row.review_status)}${row.reviewed_at ? ' (' + esc(row.reviewed_at) + ')' : ''}</p>`}`;
return [{ json: { status: 200, html: page('Enquiry review', inner) } }];

// The Approve / Take over form posts id, t and do. Validate before anything touches the database.
const b = $json.body ?? {};
const ok = /^[0-9a-f-]{36}$/i.test(b.id ?? '') && /^[0-9a-f]{32}$/i.test(b.t ?? '') && ['approve', 'takeover'].includes(b.do);
return [{ json: { id: ok ? b.id : '00000000-0000-0000-0000-000000000000', t: ok ? b.t : 'invalid', do: ok ? b.do : 'none' } }];

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const row = $('apply decision').first()?.json ?? {};
const { id, t } = $('read form').first().json;
let drafted = null;
try { drafted = $('record draft').first()?.json ?? null; } catch (e) { /* the draft step did not run */ }
let msg;
if (!row.id) {
  msg = '<h1>Nothing changed</h1><p>Already reviewed, no draft to approve, or the link is not valid.</p>';
} else if (row.review_status !== 'approved') {
  msg = '<h1>Taken over ✓</h1><p>Marked for a person to write the reply.</p>';
} else if (drafted && drafted.gmail_draft_id) {
  msg = '<h1 style="color:#1a7f37">Approved ✓</h1><p>A draft reply is waiting in the business Gmail inbox, addressed to <b>' + esc(row.from_email) +
        '</b>. <b>Nothing has been sent</b>: a person reviews it there and presses Send.</p>';
} else {
  msg = '<h1 style="color:#9a6700">Approved, but the Gmail draft could not be created</h1><p>The reply is approved and stored; copy it from the review page. ' +
        'Nothing was sent.</p><p><small>Reason: ' + esc(drafted?.draft_error || 'unknown') + '</small></p>';
}
const back = row.id || /^[0-9a-f]{32}$/.test(t) ? `<p><a href="review-staging?id=${esc(id)}&t=${esc(t)}">Back to the enquiry</a></p>` : '';
return [{ json: { status: row.id ? 200 : 409, html: `<!doctype html><html><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1"><title>Review</title>
<style>body{font:16px/1.45 system-ui,sans-serif;max-width:640px;margin:0 auto;padding:16px}</style></head>
<body>${msg}${back}</body></html>` } }];
